<script setup lang="ts">
import {computed} from 'vue';import {campusRows,educationTypes} from '../campus';import {fmt} from '../data';
const props=defineProps<{campusId?:string}>();const emit=defineEmits<{institute:[id:string]}>();
const rows=computed(()=>campusRows(props.campusId));const max=computed(()=>Math.max(...rows.value.map(r=>r.onsite+r.remote),1));const total=computed(()=>rows.value.reduce((s,r)=>s+r.onsite+r.remote,0));
</script>
<template><section class="campus-population"><header v-if="!campusId"><h3>Обучающиеся</h3><strong>{{rows.length?fmt(total):'—'}}</strong></header><div v-if="rows.length" class="population-legend"><span><i></i>Очная и очно-заочная</span><span><i></i>Заочная</span></div><div v-if="!rows.length" class="map-data-empty">Численность не указана</div><div v-for="row in rows" :key="row.id" class="population-row" :title="`${row.name}: очная и очно-заочная — ${fmt(row.onsite)}, заочная — ${fmt(row.remote)}`" :style="{'--education-color':educationTypes[row.education].color}"><button v-if="row.instituteId" class="population-name" @click="emit('institute',row.instituteId)">{{row.name}} ↗</button><span v-else class="population-name">{{row.name}}</span><b>{{fmt(row.onsite+row.remote)}}</b><div class="population-track" :aria-label="`${row.name}: очная и очно-заочная — ${fmt(row.onsite)}, заочная — ${fmt(row.remote)}`"><i :style="{width:(row.onsite/max*100)+'%'}"></i><i :style="{width:(row.remote/max*100)+'%'}"></i></div><small>{{fmt(row.onsite)}}<span v-if="row.remote"> / {{fmt(row.remote)}}</span></small></div></section></template>
